import{_ as t,o as d,c as o,a4 as a}from"./chunks/framework.B8PHay3u.js";const m=JSON.parse('{"title":"前后端分离部署","description":"","frontmatter":{},"headers":[],"relativePath":"frontend-separated-deployment.md","filePath":"frontend-separated-deployment.md","lastUpdated":1789295182000}'),c={name:"frontend-separated-deployment.md"};function r(n,e,s,p,i,h){return d(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="前后端分离部署" tabindex="-1">前后端分离部署 <a class="header-anchor" href="#前后端分离部署" aria-label="Permalink to &quot;前后端分离部署&quot;">​</a></h1><p>前端用 Vite 构建，后端与图片地址在<strong>构建阶段</strong>注入并写进静态产物，部署后改服务器环境变量不生效， 必须重新构建。</p><h2 id="构建变量" tabindex="-1">构建变量 <a class="header-anchor" href="#构建变量" aria-label="Permalink to &quot;构建变量&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>必填</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td><code>VITE_API_BASE_URL</code></td><td>分离部署时必填</td><td><code>https://api.example.com</code></td><td>后端地址；只填域名会自动补 <code>/api/v1</code>，也可填完整 API 根地址</td></tr><tr><td><code>VITE_IMAGE_BASE_URL</code></td><td>否</td><td><code>https://img.example.com</code></td><td>图床/CDN；只填域名会自动补 <code>/api/v1/files/images</code>，留空则从后端读</td></tr><tr><td><code>VITE_API_PROXY</code></td><td>否</td><td><code>http://localhost:8000</code></td><td>仅 <code>npm run dev</code> 的本地代理</td></tr><tr><td><code>VITE_BASE_PATH</code></td><td>否</td><td><code>/Electrical-Manager/demo/</code></td><td>部署到子路径时用，默认 <code>/</code></td></tr></tbody></table><p>所有 <code>VITE_*</code> 都会暴露给浏览器，禁止放密钥、Token。地址末尾可带斜杠，构建会自动清理。</p><h2 id="构建" tabindex="-1">构建 <a class="header-anchor" href="#构建" aria-label="Permalink to &quot;构建&quot;">​</a></h2><table tabindex="0"><thead><tr><th>平台</th><th>命令</th></tr></thead><tbody><tr><td>Linux</td><td><code>cd web &amp;&amp; npm ci &amp;&amp; VITE_API_BASE_URL=https://api.example.com VITE_IMAGE_BASE_URL=https://img.example.com npm run build</code></td></tr><tr><td>PowerShell</td><td><code>Set-Location web; npm ci; $env:VITE_API_BASE_URL=&#39;https://api.example.com&#39;; $env:VITE_IMAGE_BASE_URL=&#39;https://img.example.com&#39;; npm run build</code></td></tr></tbody></table><p>产物在 <code>web/dist/</code>，CD 阶段把它发布到静态站点、对象存储或 CDN 即可。</p><h2 id="环境划分" tabindex="-1">环境划分 <a class="header-anchor" href="#环境划分" aria-label="Permalink to &quot;环境划分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>环境</th><th><code>VITE_API_BASE_URL</code></th><th><code>VITE_IMAGE_BASE_URL</code></th></tr></thead><tbody><tr><td>测试</td><td><code>https://api-test.example.com</code></td><td><code>https://img-test.example.com</code></td></tr><tr><td>生产</td><td><code>https://api.example.com</code></td><td><code>https://img.example.com</code></td></tr></tbody></table><p>每套环境单独出产物，避免同一个静态包跨环境复用。</p><h2 id="后端跨域" tabindex="-1">后端跨域 <a class="header-anchor" href="#后端跨域" aria-label="Permalink to &quot;后端跨域&quot;">​</a></h2><p>后端用 <code>RefererCORSMiddleware</code>：优先按 <code>Referer</code> 解析前端站点，缺失或无效时回退 <code>Origin</code>，并为预检与正常响应（含结构化错误响应）补齐 CORS Header。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Referer: https://spares.example.com/login?redirect=/</span></span>
<span class="line"><span>Origin: https://spares.example.com</span></span>
<span class="line"><span>Access-Control-Allow-Origin: https://spares.example.com</span></span>
<span class="line"><span>Vary: Origin, Referer</span></span></code></pre></div><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>响应头</td><td>暴露 <code>Content-Disposition</code>、<code>X-Request-ID</code> 与性能头 <code>X-Response-Time</code>、<code>X-DB-Time</code>、<code>X-Compute-Time</code>、<code>X-DB-Queries</code></td></tr><tr><td>错误体</td><td>不使用 HTTP 404，错误统一为结构化业务错误体，见 <a href="/Electrical-Manager/api-error-conventions">API 错误与状态码约定</a></td></tr></tbody></table><table tabindex="0"><thead><tr><th>配置</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>APP_CORS_ALLOW_CREDENTIALS</code></td><td><code>true</code></td><td>是否允许携带凭证</td></tr><tr><td><code>APP_CORS_MAX_AGE</code></td><td><code>86400</code></td><td>预检结果缓存秒数</td></tr></tbody></table><p>正常部署时 <code>Referer</code> 所属站点应与浏览器 <code>Origin</code> 相同；浏览器不发送 <code>Referer</code> 时自动回退 <code>Origin</code>。</p><h2 id="图片-cdn-图床" tabindex="-1">图片 CDN / 图床 <a class="header-anchor" href="#图片-cdn-图床" aria-label="Permalink to &quot;图片 CDN / 图床&quot;">​</a></h2><p><code>VITE_IMAGE_BASE_URL</code> 只影响图片展示与预览；上传、删除仍走 <code>VITE_API_BASE_URL</code>。</p><table tabindex="0"><thead><tr><th>CDN 规则</th><th>要求</th></tr></thead><tbody><tr><td>代理范围</td><td>仅 <code>GET /api/v1/files/images/*</code>，不要切上传/删除接口</td></tr><tr><td>缓存键</td><td>必须包含 <code>size</code> 查询参数，否则不同尺寸预览互相覆盖</td></tr><tr><td>缓存时间</td><td>遵循后端 <code>Cache-Control</code>；文件 ID 不变则内容不变，适合长缓存</td></tr><tr><td>路径处理</td><td>转发原始路径与查询串，不要重写 <code>file_id</code></td></tr><tr><td>协议</td><td>图床与前端都用 HTTPS</td></tr></tbody></table><p>不用图床时留空 <code>VITE_IMAGE_BASE_URL</code> 即可。</p><h2 id="edgeone-pages" tabindex="-1">EdgeOne Pages <a class="header-anchor" href="#edgeone-pages" aria-label="Permalink to &quot;EdgeOne Pages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>部署配置</td><td><code>web/edgeone.json</code>（EdgeOne 项目根目录为 <code>web/</code>）</td></tr><tr><td>构建产物</td><td><code>dist/</code>（JS/CSS 在 <code>dist/yangrucheng-assets/</code>，文件名带内容 hash）</td></tr><tr><td>缓存规则</td><td><code>/yangrucheng-assets/*</code>、<code>/*.png</code>、<code>/*.jpg</code> → <code>max-age=1209600</code>（14 天）</td></tr></tbody></table><p>图片（<code>logo.png</code>、<code>qrcode.png</code>）在 <code>dist/</code> 根目录，因此 png/jpg 规则用全站后缀匹配而非限定在 <code>yangrucheng-assets/</code> 内；<code>edgeone.json</code> 的 <code>source</code> 是 URL 通配符（以 <code>/</code> 开头、最多一个 <code>*</code>）。</p>`,24)])])}const _=t(c,[["render",r]]);export{m as __pageData,_ as default};
